{"code": "def simulate_game(sequence, n=5, max_steps=100):
    """Simulate the game with proper mechanics including collisions.
    Returns (ball_ejected, steps_taken) or (None, steps_taken)."""
    # Initialize positions: balls 1..n at positions 1..n
    positions = list(range(1, n+1))

    # Track visited states for cycle detection
    visited_states = {}

    for step, move in enumerate(sequence):
        # Check for cycles
        state = tuple(positions)
        if state in visited_states:
            return None, step  # Cycle detected, game would run forever
        visited_states[state] = step

        # Apply the move
        if move == 'L':
            # Left piston: find leftmost ball(s)
            min_pos = min(positions)
            leftmost_indices = [i for i, pos in enumerate(positions) if pos == min_pos]

            if min_pos == 1:
                # Ejection from left
                # In case of multiple balls at leftmost, choose one (lowest index)
                return leftmost_indices[0] + 1, step + 1
            else:
                # Move all leftmost balls left by 1
                for i in leftmost_indices:
                    positions[i] -= 1

        elif move == 'R':
            # Right piston: find rightmost ball(s)
            max_pos = max(positions)
            rightmost_indices = [i for i, pos in enumerate(positions) if pos == max_pos]

            if max_pos == n:
                # Ejection from right
                return rightmost_indices[0] + 1, step + 1
            else:
                # Move all rightmost balls right by 1
                for i in rightmost_indices:
                    positions[i] += 1

        elif move == 'M':
            # Middle piston: find median ball
            sorted_pos = sorted(positions)
            median_idx = (len(positions) - 1) // 2
            median_pos = sorted_pos[median_idx]

            # Find balls at median position
            median_indices = [i for i, pos in enumerate(positions) if pos == median_pos]

            # Count balls on left and right of median position
            left_count = sum(1 for pos in positions if pos < median_pos)
            right_count = sum(1 for pos in positions if pos > median_pos)

            if left_count <= right_count:
                # Push left
                if median_pos == 1:
                    # Would eject from left
                    return median_indices[0] + 1, step + 1
                else:
                    # Move median balls left
                    for i in median_indices:
                        positions[i] -= 1
            else:
                # Push right
                if median_pos == n:
                    # Would eject from right
                    return median_indices[0] + 1, step + 1
                else:
                    # Move median balls right
                    for i in median_indices:
                        positions[i] += 1

            # Resolve collisions (balls can't occupy same position)
            # Sort and ensure distinct positions
            positions.sort()
            for i in range(1, len(positions)):
                if positions[i] <= positions[i-1]:
                    positions[i] = positions[i-1] + 1

        # Safety check - shouldn't be needed with cycle detection
        if step >= max_steps:
            return None, step + 1

    # Sequence completed without ejection
    return None, len(sequence)

# Test various sequences
test_sequences = [
    (['L'], "Immediate left"),
    (['R'], "Immediate right"),
    (['M'], "Middle first"),
    (['R', 'L'], "Right then left"),
    (['M', 'M', 'L'], "Middle twice then left"),
    (['L', 'L', 'L', 'L', 'L'], "All left"),
]

